/**
 * F3 (UI batch 1): ONE wording for the add, on the service detail page and the storefront too.
 *
 * "Add to plan" is the approved add wording (Leon, Nov 10; `ADD_COPY`). The buy-action resolver and the
 * storefront mapper still author "Save to plan" for the same action. `WAITLIST_COPY.saveToPlan` stays for the
 * in-plan stand-ins it was approved for; it is not the add's label anywhere a traveler adds a listing.
 *
 * WRITTEN BEFORE THE BUILD. Do not edit this file to make it pass; if a case is wrong, stop and write it up.
 *
 * Run: npx tsx --test client/src/lib/__tests__/f3-add-wording.test.ts
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { resolveBuyAction, type BuyActionBuyer, type BuyActionRow } from "@shared/buy-action";
import { ADD_COPY } from "../add-to-plan";
import { offeringActionLabel } from "../storefront-offering-action";

const BUYERS: BuyActionBuyer[] = [
  { principal: "guest", plans: "none" },
  { principal: "member", plans: "none" },
  { principal: "member", plans: "one" },
  { principal: "member", plans: "many" },
  { principal: "member", plans: "many", chipTripId: "trip-1" },
];
const base: BuyActionRow = { kind: "listing", bookability: "native", deliveryMethod: "in_person", bookingMode: "instant", hasPrice: true, hasPublishedAvailability: true, isLive: true };
const ROWS: Record<string, BuyActionRow> = {
  "info-only listing": { ...base, bookability: "info_only" },
  "custom quote": { ...base, priceType: "custom_quote" },
  "request mode": { ...base, bookingMode: "request" },
  "instant, scheduled, calendar published": base,
  "instant, no calendar stated": { ...base, hasPublishedAvailability: null },
  "instant, no price": { ...base, hasPrice: false },
  "instant artifact": { ...base, deliveryMethod: "pdf" },
  "no booking mode": { ...base, bookingMode: null },
  "unclassifiable": { ...base, deliveryMethod: null },
};

test("F3.1 every add the resolver authors reads the approved add wording", () => {
  let adds = 0;
  for (const [name, row] of Object.entries(ROWS)) {
    for (const buyer of BUYERS) {
      const action = resolveBuyAction(row, buyer);
      for (const button of [action.primary, action.secondary]) {
        if (button?.kind !== "add_to_plan") continue;
        adds += 1;
        assert.equal(button.label, ADD_COPY.addToPlan, `${name} / ${buyer.principal}:${buyer.plans}`);
      }
    }
  }
  assert.ok(adds >= 20, `the table reaches the add rows (${adds})`);
});

test("F3.2 the storefront mapper words an add the same way", () => {
  const action = resolveBuyAction(ROWS["info-only listing"], BUYERS[0]);
  assert.equal(action.primary.kind, "add_to_plan");
  assert.equal(offeringActionLabel(action), ADD_COPY.addToPlan);
});
